import { startUserLoginServer } from '../login-server';
import { getGlobalCliConfig } from '../utils/config.util';
import { MKDB_BASE_URL } from '../utils/env.util';
import logger, { withColor } from '../utils/logger.util';

const login = async (): Promise<any> => {
  const currentConfig = getGlobalCliConfig();

  if (currentConfig?.user) {
    logger.log(`already logged in as: ${withColor(currentConfig.user.name)}`);
    logger.dev.logJson(currentConfig);

    return currentConfig.user;
  }

  return new Promise((resolve) => {
    startUserLoginServer(
      () => {
        var url = `${MKDB_BASE_URL}/login/cli`;
        logger.log(`opening browser: ${url}`);
        var start =
          process.platform == 'darwin'
            ? 'open'
            : process.platform == 'win32'
            ? 'start'
            : 'xdg-open';
        require('child_process').exec(start + ' ' + url);
        logger.log('\nwaiting for login..');
      },
      (user) => resolve(user),
    );
  });
};

export default login;
